/// <summary>
/// Description of the handler
/// </summary>
/// <returns>Description</returns>
public static Description getDescription()
{
    return 'General Ledger Journal Create and Post';
}

/// <summary>
/// Validates the message type parameters
/// </summary>
/// <param name = "_messageType">Message Type</param>
/// <returns>true</returns>
public boolean validateMessageTypeParameters(OMGMessageTypeTable _messageType)
{
    return true;
}

/// <summary>
/// Processes the message (creates and posts the journal)
/// </summary>
/// <param name = "_message">Inbound message</param>
/// <returns>Response contract</returns>
public OMGInboundMessageResponseContract processMessage(OMGInboundMessageTable  _inboundMessageTable)
{
    OMGInboundMessageResponseContract           response = new OMGInboundMessageResponseContract();
    OMGTutorialLedgerJournalHeaderDataContract  headerContract;
    ;

    try
    {
        headerContract = FormJsonSerializer::deserializeObject(classNum(OMGTutorialLedgerJournalHeaderDataContract), _inboundMessageTable.Message);

        ttsbegin;

        changecompany(headerContract.parmDataAreaId())
        {
            if (this.validateJournal(headerContract.parmLedgerJournalNameId()))
            {
                LedgerJournalTable ledgerJournalTable;

                if (this.createJournal(headerContract, ledgerJournalTable))
                {
                    if (this.postJournal(ledgerJournalTable))
                    {
                        response.parmProcessedOk(true);
                        response.parmProcessingStatus(OMGProcessingStatus::Processed);
                        response.parmResponse(strFmt('Journal %1 posted successfully',ledgerJournalTable.JournalNum));
                    }
                    else
                    {
                        response.parmProcessedOk(false);
                        response.parmProcessingStatus(OMGProcessingStatus::Error);
                        response.parmResponse('Error posting journal');
                    }
                }
                else
                {
                    response.parmProcessedOk(false);
                    response.parmProcessingStatus(OMGProcessingStatus::Error);
                    response.parmResponse('Error creating journal');
                }
            }
            else
            {
                response.parmProcessedOk(false);
                response.parmProcessingStatus(OMGProcessingStatus::Error);
                response.parmResponse('Error validating journal');
            }
        }

        if (response.parmProcessedOk())
        {
            ttscommit;
        }
        else
        {
            ttsabort;
        }
    }
    catch (Exception::CLRError)
    {
        response.parmProcessed(false);
        response.parmProcessedOk(false);
        response.parmProcessingStatus(OMGProcessingStatus::Error);
        response.parmResponse(AifUtil::getClrErrorMessage());
    }

    return response;
}

/// <summary>
/// Validates the journal name
/// </summary>
/// <param name = "_journalHeader">JournalHeader</param>
/// <returns>true if journal name is found, otherwise false</returns>

protected boolean validateJournal(LedgerJournalNameId   _journalNameId)
{
    if (LedgerJournalName::exist(_journalNameId) == false)
    {
        Error(strFmt('Journal name %1 does not exist', _journalNameId));
        return false;
    }

    return true;
}

/// <summary>
/// Creates the journal header
/// </summary>
/// <param name = "_journalHeader">JournalHeader object (serialized .net)</param>
/// <param name = "_journalTable">LedgerJournalTable as OUT buffer</param>
/// <returns>true, if created OK</returns>

protected boolean createJournal(OMGTutorialLedgerJournalHeaderDataContract  _headerContract, 
                                LedgerJournalTable                          _journalTable)
{
    _journalTable.clear();
    _journalTable.initValue();
    _journalTable.JournalName   = _headerContract.parmLedgerJournalNameId();
    _journalTable.initFromLedgerJournalName();

    _journalTable.JournalNum    = JournalTableData::newTable(_journalTable).nextJournalId();
    _journalTable.Name          = _headerContract.parmName();

    if (_journalTable.validateWrite())
    {
        _journalTable.insert();

        return this.createJournalLines(_headerContract.parmLines(), _journalTable);
    }

    return false;
}

/// <summary>
/// Converts the account type from string to enum
/// </summary>
/// <param name = "_accTypeStr">account type as string</param>
/// <returns>Account type enum</returns>
protected LedgerJournalACType accountType(str _accTypeStr)
{
    switch (_accTypeStr)
    {
        case 'Ledger':
            return LedgerJournalACType::Ledger;
        case 'Cust':
            return LedgerJournalACType::Cust;
        case 'Vend':
            return LedgerJournalACType::Vend;
        case 'Proj':
            return LedgerJournalACType::Project;
        default:
            throw error(strFmt('Account type %1 not supported', _accTypeStr));
    }
}

    /// <summary>
    /// Creates the journal lines in the .net header object
    /// </summary>
    /// <param name = "_journalHeader">.net header object</param>
    /// <param name = "_journalTable">LedgderJournalTable buffer</param>
    /// <returns>true if created OK</returns>    
    protected boolean createJournalLines(List               _journalLineList, 
                                         LedgerJournalTable _journalTable)
    {        
        LedgerJournalTrans                          ledgerJournalTrans;
        OMGTutorialLedgerJournalLineDataContract    lineDataContract;

        RecordInsertList    lineInsertList      = new RecordInsertList(tableNum(LedgerJournalTrans));
        LedgerJournalEngine ledgerJournalEngine = LedgerJournalEngine::construct(_journalTable.JournalType);
        ListEnumerator      lineListEnumerator  = _journalLineList.getEnumerator();
        Counter             counter             = 1;        
        ;

        ledgerJournalEngine.newJournalActive(_journalTable);

        while (lineListEnumerator.moveNext())
        {
            lineDataContract = lineListEnumerator.current();
            ledgerJournalTrans.clear();
            ledgerJournalTrans.initValue();

            ledgerJournalEngine.initValue(ledgerJournalTrans);

            ledgerJournalTrans.JournalNum = _journalTable.JournalNum;
            ledgerJournalTrans.LineNum = counter;

            ledgerJournalTrans.TransDate = lineDataContract.parmTransDate();
            //ledgerJournalTrans.AccountType = this.accountType(lineDataContract.parmAccounType());
            ledgerJournalTrans.AccountType = lineDataContract.parmAccounType();

            switch (ledgerJournalTrans.AccountType)
            {
                case LedgerJournalACType::Ledger:
// TODO Fix                    
//ledgerJournalTrans.LedgerDimension = LedgerAccountDimensionResolver::newResolver(lineDataContract.parmAccountDisplayValue()).resolve();
                    break;
                case LedgerJournalACType::Cust:
                case LedgerJournalACType::Vend:
                case LedgerJournalACType::Project:
                    // TODO Fix
//ledgerJournalTrans.LedgerDimension = LedgerDynamicAccountHelper::getDynamicAccountFromAccountNumber(lineDataContract.parmAccountDisplayValue(), ledgerJournalTrans.AccountType);
                    break;
            }

            ledgerJournalTrans.CurrencyCode     = lineDataContract.parmCurrencyCode();
            //ledgerJournalTrans.CurrncyModified(ledgerJournalTrans);
            ledgerJournalTrans.AmountCurDebit   = lineDataContract.parmDebitAmount();
            ledgerJournalTrans.AmountCurCredit  = lineDataContract.parmCreditAmount();
            ledgerJournalTrans.Invoice          = lineDataContract.parmInvoiceId();
            ledgerJournalTrans.Due              = lineDataContract.parmDueDate();
            ledgerJournalTrans.Txt              = lineDataContract.parmTxt();
            ledgerJournalTrans.Payment          = lineDataContract.parmPaymTermId();
            ledgerJournalTrans.TaxItemGroup     = lineDataContract.parmTaxItemGroup();
            ledgerJournalTrans.TaxGroup         = lineDataContract.parmTaxGroupJournal();

            ledgerJournalTrans.defaultRow();

            if (ledgerJournalTrans.validateWrite())
            {
                lineInsertList.add(ledgerJournalTrans);
            }
            else
            {
                lineInsertList = null;
                return false;
            }

            ledgerJournalEngine.write(ledgerJournalTrans);

            counter++;
        }

        lineInsertList.insertDatabase();

        return true;
    }

/// <summary>
/// Post the journal
/// </summary>
/// <param name = "_ledgerJournalTable">LedgerJournalTable</param>
/// <returns>true if posted ok, otherwise false</returns>
protected boolean postJournal(LedgerJournalTable _ledgerJournalTable)
{
    return true;    // TODO Fix
    LedgerJournalCheckPost journalCheckPost = LedgerJournalCheckPost::newLedgerJournalTable(_ledgerJournalTable, NoYes::Yes, NoYes::No);

    journalCheckPost.runOperation();

    _ledgerJournalTable.reread();

    return _ledgerJournalTable.Posted == NoYes::Yes;
}
